/bin/bash -lc "python - <<'PY'
import cv2,numpy as np
A=np.load('source_pixels.npz')['rgb']
for i in range(0,41,2):
 im=A[i]
 # Try Hough on red-excess / saturation and on luminance, report candidate circles upper area
 chans=[cv2.cvtColor(im,cv2.COLOR_RGB2GRAY), np.clip(im[:,:,0].astype(int)-im[:,:,2].astype(int)+100,0,255).astype('uint8')]
 cand=[]
 for ci,ch in enumerate(chans):
  ch=cv2.GaussianBlur(ch,(5,5),1)
  cs=cv2.HoughCircles(ch,cv2.HOUGH_GRADIENT,1,minDist=10,param1=50,param2=12,minRadius=8,maxRadius=22)
  if cs is not None:
   for x,y,r in cs[0]:
    if 55<y<95 and x>90: cand.append((ci,round(float(x),1),round(float(y),1),round(float(r),1)))
 print(i,cand)
PY"
